-- Lockdown (docs/plan.md §1.243, docs/lockdown-plan.md, stream K0): `tenant.locked_at` and
-- `tenant.lock` lock one client; `platform_lock` (one row at most) locks every client. The check is
-- `app_scope_tenant_ids`, which `inScope` (packages/db/src/client.ts) will call in the statement
-- that already sets `app.tenant_ids` (stream K1), so every scope of client data goes through it.
-- New columns, a new table, new functions and a wider audit insert policy: nothing reads them yet,
-- so the previous Worker keeps working. Generated by drizzle-kit from packages/db/src/schema.ts;
-- the functions, the grants and the audit rows' insert policy at the end are hand-written.
CREATE TABLE "platform_lock" (
	"id" boolean PRIMARY KEY DEFAULT true NOT NULL,
	"locked_by" uuid NOT NULL,
	"locked_at" timestamp with time zone DEFAULT now() NOT NULL,
	"reason" text NOT NULL,
	CONSTRAINT "platform_lock_one_row_check" CHECK ("platform_lock"."id"),
	CONSTRAINT "platform_lock_reason_check" CHECK (length("platform_lock"."reason") between 1 and 500)
);
