-- The clients a scope may see, given the locks. `p_mode`:
--   'one'         withTenant (a run, a portal request, a webhook): raises `client_locked`
--                 (SQLSTATE MZLCK) when its client is locked, or everything is. The transaction
--                 aborts, so nothing after it in the transaction runs.
--   'some'        withTenants and withOperator (sweeps, the back office's lists): the ids that
--                 aren't locked; none while everything is locked.
--   'investigate' the security officer's reads of a locked client: the ids as given, and only in
--                 a read-only transaction, so an investigation can never write. Who may open it is
--                 decided in code (stream K2); the database only holds it to reading.
-- Not SECURITY DEFINER: `tenant` and `platform_lock` have no row-level security and cs_runtime
-- reads both. STABLE, so it reads the locks as of the statement that calls it: no cache.
-- DECISION: one function with a mode rather than three, so `inScope` keeps one statement.
CREATE FUNCTION app_scope_tenant_ids(p_ids uuid[], p_mode text) RETURNS uuid[]
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, public
AS $$
DECLARE
  ids uuid[] := coalesce(p_ids, '{}'::uuid[]);
  locked uuid[];
BEGIN
  IF p_mode = 'investigate' THEN
    IF current_setting('transaction_read_only') <> 'on' THEN
      RAISE EXCEPTION 'an investigation scope needs a read-only transaction'
        USING ERRCODE = 'read_only_sql_transaction';
    END IF;
    RETURN ids;
  END IF;
  IF p_mode IS NULL OR p_mode NOT IN ('one', 'some') THEN
    RAISE EXCEPTION 'unknown scope mode: %', p_mode USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF EXISTS (SELECT 1 FROM public.platform_lock) THEN
    locked := ids;
  ELSE
    SELECT coalesce(array_agg(t.id), '{}'::uuid[]) INTO locked
    FROM public.tenant t
    WHERE t.id = any(ids) AND t.locked_at IS NOT NULL;
  END IF;
  IF cardinality(locked) = 0 THEN
    RETURN ids;
  END IF;
  IF p_mode = 'one' THEN
    RAISE EXCEPTION 'client_locked' USING ERRCODE = 'MZLCK',
      DETAIL = 'This account is locked down.';
  END IF;
  RETURN array(SELECT x FROM unnest(ids) AS x WHERE NOT x = any(locked));
END
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app_scope_tenant_ids(uuid[], text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_scope_tenant_ids(uuid[], text) TO cs_runtime;
--> statement-breakpoint

-- Global table, as `tenant`: no tenant_id, no row-level security. Unlocking everything deletes the
-- row; no UPDATE, so a lock's who, when and why can't be rewritten while it stands.
GRANT SELECT, INSERT, DELETE ON platform_lock TO cs_runtime;
--> statement-breakpoint

-- Every request is audited (invariant 14), a locked client's included: its 423s and the lock and
-- unlock routes. `inScope` keeps, in `app.locked_tenant_ids`, the clients a transaction asked for
-- and the lockdown left out (clients the session or job was entitled to), so an audit row may name
-- one of them. Audit rows only: every other table still sees only `app.tenant_ids`. Wider than
-- before, so the previous Worker's inserts pass as they did.
CREATE FUNCTION app_locked_tenant_ids() RETURNS uuid[]
LANGUAGE sql STABLE PARALLEL SAFE AS $$
  SELECT coalesce(nullif(current_setting('app.locked_tenant_ids', true), '')::uuid[], '{}'::uuid[])
$$;
--> statement-breakpoint
DROP POLICY audit_write ON audit_event;
--> statement-breakpoint
CREATE POLICY audit_write ON audit_event FOR INSERT TO PUBLIC
  WITH CHECK (
    tenant_id IS NULL
    OR tenant_id = any(app_tenant_ids())
    OR tenant_id = any(app_locked_tenant_ids()));
